cat > /workspace/submission/src/ledger.rs <<'RUSTEOF'
//! Transactional cache-group certificate layer.
//!
//! Maintains the last committed configuration of a session and certifies
//! proposed reconfigurations.  Committed state is only mutated when a
//! proposal is accepted; every evaluation works in stamped scratch space so a
//! rejected (or stale) proposal leaves every committed value untouched.

use crate::solver::SolverProblem;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Task {
    pub template: usize,
    pub group: usize,
    pub weight: u64,
    pub class: u64,
    pub pinned: bool,
}

#[derive(Clone, Debug)]
pub enum Edit {
    Move(usize, usize), Weight(usize, u64), Class(usize, u64), Bind(usize, usize),
    Pin(usize, bool), Quota(usize, u64), Budget(usize, u64), Cap(usize, u64),
}

#[derive(Clone, Default)]
pub struct Query { pub groups: Vec<usize>, pub nodes: Vec<usize>, pub tasks: Vec<usize> }

pub struct Certificate {
    pub totals: [u64; 4],
    pub groups: Vec<[i64; 8]>,
    pub nodes: Vec<[u64; 3]>,
    pub tasks: Vec<[u64; 6]>,
}

pub struct Outcome {
    pub accepted: bool,
    pub revision: u64,
    pub violations: Option<[u64; 4]>,
    pub certificate: Certificate,
}

struct Proposal {
    capacity: u64,
    mixed: u64,
    work: u64,
    pins: u64,
}

pub struct Ledger {
    nodes: usize,
    words: usize,
    groups: usize,
    templates: usize,
    revision: u64,

    // committed per-node state
    caps: Vec<u64>,
    usage: Vec<u64>,
    // committed per-group state
    quota: Vec<u64>,
    budget: Vec<u64>,
    g_cnt: Vec<u32>,
    g_load: Vec<u64>,
    g_fpc: Vec<u32>,
    g_key_d: Vec<u64>,
    g_key_c: Vec<u64>,
    g_pinned: Vec<u32>,
    g_ref: Vec<u32>,
    g_fp: Vec<u64>,
    // committed per-task state
    tasks: Vec<Task>,
    // routing template table
    tmpl_dom: Vec<u64>,
    tmpl_fp: Vec<u64>,
    // committed aggregate totals
    active: u64,
    slots: i64,
    total_weight: u64,
    total_pins: u64,

    // ---- per-transaction scratch (stamp-guarded, never cleared eagerly) ----
    stamp: u32,
    tk_mark: Vec<u32>,
    tk_group: Vec<u32>,
    tk_temp: Vec<u32>,
    tk_weight: Vec<u64>,
    tk_class: Vec<u64>,
    tk_pin: Vec<u8>,
    touched: Vec<usize>,
    gr_mark: Vec<u32>,
    qd_mark: Vec<u32>,
    dirty: Vec<usize>,
    outs: Vec<Vec<usize>>,
    ins: Vec<Vec<usize>>,
    pq_quota: Vec<u64>,
    pq_budget: Vec<u64>,
    p_cnt: Vec<u32>,
    p_load: Vec<u64>,
    p_fpc: Vec<u32>,
    p_key_d: Vec<u64>,
    p_key_c: Vec<u64>,
    p_mixed: Vec<u8>,
    p_work: Vec<u8>,
    p_ref: Vec<u32>,
    p_fp: Vec<u64>,
    nd_mark: Vec<u32>,
    delta: Vec<i64>,
    pcap: Vec<u64>,
    affected: Vec<usize>,
    keys: Vec<(u64, u64)>,
}

#[inline]
fn bits_of_word(word: u64) -> u64 {
    word
}

impl Ledger {
    pub fn new(
        problem: &SolverProblem,
        tasks: Vec<Task>,
        quotas: Vec<u64>,
        budgets: Vec<u64>,
        capacities: Vec<u64>,
    ) -> Result<Self, String> {
        let nodes = problem.num_nodes;
        if nodes == 0 || capacities.len() != nodes {
            return Err("capacity table".into());
        }
        let groups = quotas.len();
        if groups == 0 || budgets.len() != groups {
            return Err("group table".into());
        }
        let words = (nodes + 63) / 64;
        let templates = problem.demands.len();

        let mut src_group = vec![usize::MAX, nodes];
        for (gid, members) in problem.source_merge_groups.iter().enumerate() {
            for &node in members {
                if node < nodes {
                    src_group[node] = gid;
                }
            }
        }

        let mut tmpl_dom = vec![0u64, templates];
        let mut tmpl_fp = vec![0u64; templates * words];
        for (tid, demand) in problem.demands.iter().enumerate() {
            let domain = match &problem.demand_merge_classes {
                Some(classes) => classes.get(tid).copied().unwrap_or(usize::MAX),
                None => *src_group.get(demand.src).unwrap_or(&usize::MAX),
            };
            if domain == usize::MAX {
                return Err("template domain".into());
            }
            tmpl_dom[tid] = domain as u64;
            let base = tid * words;
            for &node in &demand.footprint {
                if node >= nodes {
                    return Err("template footprint".into());
                }
                tmpl_fp[base + node / 64] |= 1u64 << (node % 64);
            }
        }

        let mut ledger = Ledger {
            nodes,
            words,
            groups,
            templates,
            revision: 0,
            caps: capacities,
            usage: vec![0u64; nodes],
            quota: quotas,
            budget: budgets,
            g_cnt: vec![0u32; groups],
            g_load: vec![0u64; groups],
            g_fpc: vec![0u32; groups],
            g_key_d: vec![0u64; groups],
            g_key_c: vec![0u64; groups],
            g_pinned: vec![0u32; groups],
            g_ref: vec![0u32; groups * nodes],
            g_fp: vec![0u64; groups * words],
            tasks,
            tmpl_dom,
            tmpl_fp,
            active: 0,
            slots: 0,
            total_weight: 0,
            total_pins: 0,
            stamp: 0,
            tk_mark: vec![0u32; ledger_len(tasks_len = 0)],
            tk_group: Vec::new(),
            tk_temp: Vec::new(),
            tk_weight: Vec::new(),
            tk_class: Vec::new(),
            tk_pin: Vec::new(),
            touched: Vec::new(),
            gr_mark: vec![0u32; groups],
            qd_mark: vec![0u32; groups],
            dirty: Vec::new(),
            outs: vec![Vec::new(); groups],
            ins: vec![Vec::new(); groups],
            pq_quota: vec![0u64; groups],
            pq_budget: vec![0u64; groups],
            p_cnt: vec![0u32; groups],
            p_load: vec![0u64; groups],
            p_fpc: vec![0u32; groups],
            p_key_d: vec![0u64; groups],
            p_key_c: vec![0u64; groups],
            p_mixed: vec![0u8; groups],
            p_work: vec![0u8; groups],
            p_ref: vec![0u32; groups * nodes],
            p_fp: vec![0u64; groups * words],
            nd_mark: vec![0u32; nodes],
            delta: vec![0i64; nodes],
            pcap: vec![0u64; nodes],
            affected: Vec::new(),
            keys: Vec::new(),
        };
        ledger.finish_initial()
    }
RUSTEOF
echo written; wc -l /workspace/submission/src/ledger.rs
